  hl.exec_cmd('hyprctl keyword monitor ",dpms,off"')
end)


----------------------
---- HYPRSPLIT ------
----------------------
-- Workspaces 1-10 100% INDEPENDIENTES por monitor (libreria lua hyprsplit).
-- eDP-1 -> IDs reales 1-10, HDMI-A-1 -> IDs reales 11-20. Los binds SUPER+N
-- actuan sobre la monitor ACTUAL (sin saltar al otro monitor).
-- Los workspaces se renombran al ordinal (1-9 y "0" para el 10) para que el bar
-- de Caelestia muestre 1-10 identicos en ambos monitores (el 10 se ve como "0",
-- convencion de Hyprland: SUPER+0 = workspace 10).
package.path = os.getenv("HOME") .. "/.config/hypr/?.lua;" .. os.getenv("HOME") .. "/.config/hypr/?/init.lua;" .. package.path

local hs = require("hyprsplit")
hs.config({ num_workspaces = 10, persistent_workspaces = true })
hs.monitor_priority({ "eDP-1", "HDMI-A-1" })

local function hyprsplit_ordinal(ws_id)
    local nws = hs.get_config("num_workspaces") or 10
    return ((ws_id - 1) % nws) + 1
end

local function hyprsplit_rename(ws)
    if not ws or ws.special then
        return
    end
    local ordinal = hyprsplit_ordinal(ws.id)
    local name = tostring(ordinal == 10 and 0 or ordinal)
    if ws.name ~= name then
        hl.dispatch(hl.dsp.workspace.rename({ workspace = ws.id, name = name }))
    end
end

-- GLOBAL a proposito: el re-renombrado diferido (exec_cmd -> hyprctl eval) la invoca
function hyprsplit_rename_all()
    for _, ws in ipairs(hl.get_workspaces()) do
        hyprsplit_rename(ws)
    end
end

-- Los eventos hl.on (workspace.created, active, change...) NO disparan de forma
-- fiable en esta build 0.56.2-Maple, asi que el renombrado a ordinal se ejecuta
-- tras cada bind de workspace (wrapper) y en config.reloaded / hyprland.start.
-- Los workspaces persistentes pueden materializar DESPUES de estos handlers, por
-- eso se re-lanza el renombrado 1.2s mas tarde via hyprctl eval.
local function hyprsplit_rename_soon()
    hl.exec_cmd([[sh -c 'sleep 1.2; hyprctl eval "hyprsplit_rename_all()"']])
end

local function hyprsplit_wrap(dispatch_fun)
    return function()
        dispatch_fun()
        hyprsplit_rename_all()
    end
end

hl.on("config.reloaded", function()
    hyprsplit_rename_all()
    hyprsplit_rename_soon()
end)
hl.on("hyprland.start", function()
    hyprsplit_rename_all()
    hyprsplit_rename_soon()
end)


