hl.bind(mainMod .. " + D",       hl.dsp.exec_cmd("qs -c caelestia ipc call drawers toggle launcher"))
hl.bind(mainMod .. " + Tab",     hl.dsp.exec_cmd("qs -c caelestia ipc call drawers toggle dashboard"))
hl.bind(mainMod .. " + Escape",  hl.dsp.exec_cmd("qs -c caelestia ipc call drawers toggle session"))
hl.bind(mainMod .. " + N",       hl.dsp.exec_cmd("qs -c caelestia ipc call drawers toggle nexus"))
hl.bind(mainMod .. " + S",       hl.dsp.exec_cmd("qs -c caelestia ipc call drawers toggle sidebar"))
hl.bind(mainMod .. " + U",       hl.dsp.exec_cmd("qs -c caelestia ipc call drawers toggle utilities"))
hl.bind(mainMod .. " + SHIFT + D", hl.dsp.exec_cmd("qs -c caelestia ipc call drawers toggle showall"))

-- Screenshot & Screen Recording
hl.bind("Print",             hl.dsp.exec_cmd("screenshot"),        { locked = true })
hl.bind("SUPER + SHIFT + S", hl.dsp.exec_cmd("screenshot --area"), { locked = true })
hl.bind("SHIFT + Print",     hl.dsp.exec_cmd("screenshot --area"), { locked = true })
hl.bind("ALT + F9",          hl.dsp.exec_cmd("gsr-toggle"),        { locked = true })
hl.bind("ALT + Z",           hl.dsp.exec_cmd("gsr-ui"),            { locked = true })

-- Move focus with mainMod + arrow keys
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }))

-- Move active window to the other monitor with mainMod + SHIFT + arrows
hl.bind(mainMod .. " + SHIFT + right", hl.dsp.window.move({ monitor = "HDMI-A-1" }))
hl.bind(mainMod .. " + SHIFT + left",  hl.dsp.window.move({ monitor = "eDP-1" }))

-- Switch workspaces 1-10 en la monitor ACTUAL (100% independientes, hyprsplit)
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key,         hyprsplit_wrap(hs.dsp.focus({ workspace = i })))
    hl.bind(mainMod .. " + SHIFT + " .. key, hyprsplit_wrap(hs.dsp.window.move({ workspace = i, follow = true })))
end

