-- Scroll through existing workspaces (per monitor, excluyendo vacios) with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hyprsplit_wrap(hs.dsp.focus({ workspace = "e+1" })))
hl.bind(mainMod .. " + mouse_up",   hyprsplit_wrap(hs.dsp.focus({ workspace = "e-1" })))

-- Rescatar ventanas "perdidas" (p.ej. al desenchufar un monitor) con SUPER + G
hl.bind(mainMod .. " + G", hyprsplit_wrap(hs.dsp.grab_rogue_windows()))

